def static_string_literal_node?(node)
  @interpolation_profile = interpolation_profile_store
  return false unless node

  result = if node.str_type?
             true
           elsif node.dstr_type?
             !interpolation_begin_present?(node) && dstr_child_all_static?(node)
           else
             false
           end
  @interpolation_profile[:static] = result
  result
end

